on conflict ("CO_MODELO") do update
   set "NO_MODELO" = excluded."NO_MODELO", "DS_CONFIGURACAO" = excluded."DS_CONFIGURACAO", "ST_ATIVO" = 'S', "DT_ATUALIZACAO" = now();

do $$
declare
  v_modelo record;
begin
  for v_modelo in select * from public."TB_REGRA_ANALISE_MODELO" loop
    perform private."FC_VALIDAR_REGRA_ANALISE"(v_modelo."DS_CONFIGURACAO");
  end loop;
end;
$$;

insert into public."TB_ORIGEM_ANALISE_EDITAL" ("CO_MONITORAMENTO", "TP_ORIGEM")
select m.id, 'PLANILHA'
  from public."TB_MONITORAMENTO_INDIGENA" m
 where m."CO_AREA" = 'projetos' and private."FC_NUMERO_EDITAL"(m.edital) = '93/2026'
on conflict ("CO_MONITORAMENTO") do nothing;

select "CO_MODELO", "NO_MODELO", jsonb_array_length("DS_CONFIGURACAO" -> 'blocos') as blocos
  from public."TB_REGRA_ANALISE_MODELO" order by 1;

commit;
